<?php if(!defined('ABSPATH'))exit;if($role!=='admin'){echo '<p>Access denied.</p>';return;} global $wpdb;$t=$wpdb->prefix; $items=$wpdb->get_results("SELECT * FROM {$t}rp_inventory_items ORDER BY name"); ?>
<h1 class="page-title">Inventory</h1>
<div class="p-card"><h3 class="p-card-title mb-12">Add Inventory Item</h3><form method="post"><?php wp_nonce_field('rp_inventory_action'); ?><input type="hidden" name="rp_inventory_action" value="add_item"><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px"><input class="form-input" name="name" required placeholder="Item name"><input class="form-input" name="sku" placeholder="SKU"><input class="form-input" name="unit" value="pcs" placeholder="Unit"><input class="form-input" name="stock_qty" type="number" step="0.001" placeholder="Opening stock"><input class="form-input" name="reorder_level" type="number" step="0.001" placeholder="Reorder level"><input class="form-input" name="cost_price" type="number" step="0.01" placeholder="Cost price"><input class="form-input" name="sell_price" type="number" step="0.01" placeholder="Sell price"></div><button class="btn btn-primary" type="submit">Add Item</button></form></div>
<div class="p-card"><h3 class="p-card-title mb-12">Stock Movement</h3><form method="post"><input type="hidden" name="rp_inventory_action" value="movement"><?php wp_nonce_field('rp_inventory_action'); ?><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px"><select class="form-select" name="item_id" required><?php foreach($items as $i):?><option value="<?php echo (int)$i->id;?>"><?php echo esc_html($i->name);?> — <?php echo esc_html($i->stock_qty.' '.$i->unit);?></option><?php endforeach;?></select><select class="form-select" name="movement_type"><option value="in">Stock In</option><option value="out">Stock Out</option><option value="adjust">Set Stock</option></select><input class="form-input" name="qty" type="number" step="0.001" min="0" required placeholder="Quantity"><input class="form-input" name="reference" placeholder="Reference"><input class="form-input" name="notes" placeholder="Notes"></div><button class="btn btn-secondary" type="submit">Save Movement</button></form></div>
<div class="p-card"><h3 class="p-card-title mb-12">Current Stock</h3><?php if($items):?><div style="overflow:auto"><table class="rp-table" style="width:100%"><thead><tr><th>Item</th><th>SKU</th><th>Stock</th><th>Reorder</th><th>Cost</th><th>Status</th></tr></thead><tbody><?php foreach($items as $i):$low=(float)$i->stock_qty <= (float)$i->reorder_level;?><tr><td><?php echo esc_html($i->name);?></td><td><?php echo esc_html($i->sku);?></td><td><strong><?php echo esc_html($i->stock_qty.' '.$i->unit);?></strong> <?php if($low):?><span class="badge badge-cancelled">LOW</span><?php endif;?></td><td><?php echo esc_html($i->reorder_level);?></td><td>Rs. <?php echo number_format((float)$i->cost_price,2);?></td><td><?php echo esc_html(ucfirst($i->status));?></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty-state"><p>No inventory items yet.</p></div><?php endif;?></div>